/// 앱마다 테마가 달라 색은 Theme.of(context)에서 가져온다.
class UpdateScreen extends StatefulWidget {
  const UpdateScreen({super.key});

  @override
  State<UpdateScreen> createState() => _UpdateScreenState();
}

enum _Stage { idle, checking, upToDate, available, downloading, ready }

class _UpdateScreenState extends State<UpdateScreen> {
  final _svc = UpdateService.instance;
  _Stage _stage = _Stage.idle;
  UpdateInfo? _latest;
  String? _error;
  String? _apkPath;
  int _received = 0;
  int _total = -1;

  @override
  void initState() {
    super.initState();
    _init();
  }

  Future<void> _init() async {
    await _svc.loadCurrent();
    if (!mounted) return;
    setState(() {});
    // iOS 빌드 번호는 TestFlight 워크플로의 실행 번호라 안드로이드 릴리스의
    // latest.json 과는 다른 수열이다 — 견주지 않고 TestFlight 안내만 한다.
    if (Platform.isAndroid) _check();
  }

  Future<void> _check() async {
    setState(() {
      _stage = _Stage.checking;
      _error = null;
    });
    try {
      final info = await _svc.fetchLatest();
      if (!mounted) return;
      setState(() {
        _latest = info;
        _stage =
            UpdateService.isNewer(
              current: _svc.currentBuild,
              latest: info.build,
            )
            ? _Stage.available
            : _Stage.upToDate;
      });
    } catch (e) {
      if (!mounted) return;
      setState(() {
        _stage = _Stage.idle;
        _error = _message(e);
      });
    }
  }

  Future<void> _download() async {
    setState(() {
      _stage = _Stage.downloading;
      _error = null;
      _received = 0;
      _total = _latest?.size ?? -1;
    });
    try {
      final file = await _svc.download(
        onProgress: (received, total) {
          if (!mounted) return;
          setState(() {
            _received = received;
            if (total > 0) _total = total;
          });
        },
      );
      if (!mounted) return;
      setState(() {
        _apkPath = file.path;
        _stage = _Stage.ready;
      });
      _install();
    } catch (e) {
      if (!mounted) return;
      setState(() {
        _stage = _Stage.available;
        _error = _message(e);
      });
    }
  }

  Future<void> _install() async {
    final path = _apkPath;
    if (path == null) return;
    try {
      final r = await _svc.install(path);
      if (!mounted) return;
      if (r == InstallResult.needPermission) {
        setState(
          () => _error =
              tr(

;

